  const en = tokenizeEn(need);
  const zh = tokenizeZh(need);
  const scored = [];
  for (const r of recipes) {
    let score = 0;
    const hits = [];
    const corpus = (r.name + " " + r.nameEn + " " + r.description + " " + r.descriptionEn + " " + (r.tags ?? []).join(" ")).toLowerCase();
